//! Disposable benchmark of existing String search and bracket scanning.
#[path = "../tests/support/oop.rs"]
mod oop;
use birnam_abi::{size, Oop};
unsafe extern "C" { fn clock_gettime_nsec_np(clock: u32) -> u64; }
fn main() {
    let h = oop::bootstrap();
    let q = h.scope();
    let integer = h.named(b"Integer").unwrap();
    let gc = h.named(b"GC").unwrap();
    let nil = h.named(b"nil").unwrap();
    let hit = q.string(b"x").unwrap();
    let miss = q.string(b"y").unwrap();
    let empty = q.string(b"").unwrap();
    q.call(gc, b"automaticCollection:", &[size(0).unwrap()]).unwrap();
    for length in [64, 4096, 1048576] {
        let source = q.string(&vec![b'x'; length]).unwrap();
        let cases: &[(&str, &[u8], &[Oop], bool)] = &[
            ("early", b"indexOf:", &[hit], false),
            ("empty", b"indexOf:", &[empty], false),
            ("miss", b"indexOf:", &[miss], true),
            ("depth", b"bracketDepth", &[], false),
        ];
        for &(name, selector, args, expect_nil) in cases {
            let selector = q.keep(h.intern(selector).unwrap()).unwrap();
            let calls = if length == 1048576 {
                if name == "early" || name == "empty" {2048} else {32}
            } else if length == 4096 {2048} else {20000};
            for _ in 0..10 { unsafe { h.id.send(source, selector, args).unwrap(); } }
            for _ in 0..5 {
                q.call(gc, b"collectPrecisely", &[]).unwrap();
                let mut last = nil;
                let start = unsafe { clock_gettime_nsec_np(16) };
                for _ in 0..calls { last = unsafe { h.id.send(source, selector, args).unwrap() }; }
                let elapsed = unsafe { clock_gettime_nsec_np(16) } - start;
                if expect_nil { assert_eq!(last, nil); } else {
                    let word = q.call(integer, b"wordOf:", &[last]).unwrap();
                    assert_eq!(q.word_bits(word).unwrap(), 0);
                }
                println!("{length} {name} {calls} {elapsed}");
            }
        }
    }
}
